#pragma once
#include <QByteArray>
inline QByteArray crewPortal(){return R"PORTAL(<!doctype html>
<html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cuebase · Crew</title>
<style>body{font:13px system-ui;background:#24262a;color:#e2e5ea;margin:0}main{max-width:1100px;margin:auto;padding:24px}header{display:flex;align-items:center;gap:12px;margin-bottom:20px}h1{font-size:20px;margin:0}h2{font-size:15px}button,input,textarea,select{font:inherit;color:inherit;background:#3b3f46;border:1px solid #535862;border-radius:5px;padding:7px}button{cursor:pointer}button:hover{background:#4c5563}section{border:1px solid #454b54;border-radius:10px;padding:16px;margin:14px 0;overflow:auto}table{border-collapse:collapse;width:100%}td,th{text-align:left;padding:5px;border-bottom:1px solid #41454c}td input{box-sizing:border-box;width:100%;min-width:100px}textarea{display:block;width:95%;min-height:50px}label{display:block;margin:12px 0}#status{color:#adc6e3}#error{color:#efb08c;white-space:pre-wrap}.right{margin-left:auto}small{color:#aab1bd}button:disabled{opacity:.4;cursor:default}</style>
<main><header><h1>Cuebase / Crew</h1><span class="right" id="role"></span><button id="refresh">Refresh</button><button id="save">Save changes</button></header>
<section id="login"><h2>Join the production</h2><p>Enter the session code supplied by your Cuebase host. Check the server certificate fingerprint with your host before entering the code.</p><input type="password" id="code" autocomplete="off" placeholder="Session code"><button id="join">Connect</button></section>
<p id="status">Host controls broadcast and replay. This workspace edits production plans and exposed text fields.</p><p id="error"></p><div id="content"></div></main>
<script>
let token='',data=null,dirty=false;const el=id=>document.getElementById(id);const schemas={crew:['Name','Department','Role','Contact','Call time'],tasks:['Task','Assignee','Status','Due','Program','Notes'],schedule:['Time','Program','Item','Owner','Duration','Location'],script:['Time','Program','Video / action','Audio / words']};
function node(tag,text){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n}
function mark(){dirty=true;el('status').textContent='Unsaved changes';}
function render(){el('content').replaceChildren();el('role').textContent=data.role;el('save').disabled=data.role!=='Editor';
for(const [key,columns] of Object.entries(schemas)){const section=node('section'),title=node('h2',key==='script'?'Audio / visual rundown':key[0].toUpperCase()+key.slice(1));section.append(title);const table=node('table'),head=node('tr');columns.forEach(c=>head.append(node('th',c)));head.append(node('th',''));table.append(head);const rows=data.production[key]||[];data.production[key]=rows;
rows.forEach((row,index)=>{const tr=node('tr');columns.forEach((_,i)=>{const td=node('td'),input=node('input');input.value=row['c'+i]||'';input.maxLength=2000;input.disabled=data.role!=='Editor';input.oninput=()=>{row['c'+i]=input.value;mark()};td.append(input);tr.append(td)});const td=node('td'),remove=node('button','Remove');remove.disabled=data.role!=='Editor';remove.onclick=()=>{rows.splice(index,1);mark();render()};td.append(remove);tr.append(td);table.append(tr)});section.append(table);const add=node('button','+ Add');add.disabled=data.role!=='Editor';add.onclick=()=>{rows.push({id:crypto.randomUUID()});mark();render()};section.append(add);el('content').append(section)}
const sheet=node('section');sheet.append(node('h2','Call sheet'));data.production.callSheet ||= {};for(const name of ['Production','Date','Call time','Location','Address','Parking','Emergency contact','Notes']){const label=node('label',name),input=name==='Notes'?node('textarea'):node('input');input.value=data.production.callSheet[name]||'';input.maxLength=4000;input.disabled=data.role!=='Editor';input.oninput=()=>{data.production.callSheet[name]=input.value;mark()};label.append(input);sheet.append(label)}el('content').append(sheet);
const texts=node('section');texts.append(node('h2','Screen element text'));if(!data.fields.length)texts.append(node('p','Expose text fields in Build to edit them here.'));data.fields.forEach(field=>{const label=node('label',field.elementName+' / '+field.label),input=node('textarea');input.value=field.value;input.maxLength=10000;input.disabled=data.role!=='Editor';input.oninput=()=>{field.value=input.value;mark()};label.append(input);texts.append(label)});el('content').append(texts);
const audit=node('section');audit.append(node('h2','Recent changes'));(data.production.audit||[]).slice(-15).reverse().forEach(a=>audit.append(node('p',a.time+' · '+a.author)));el('content').append(audit);}
async function request(method,body){const response=await fetch('/api/session',{method,headers:{'Authorization':'Bearer '+token,'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined,cache:'no-store'});const value=await response.json();if(!response.ok)throw Error(value.error||'Request failed');return value}
async function load(){try{if(dirty&&!confirm('Discard your unsaved changes and load the current host version?'))return;data=await request('GET');dirty=false;el('login').hidden=true;el('error').textContent='';el('status').textContent='Connected · revision '+data.revision;render()}catch(e){el('error').textContent=e.message}}
el('join').onclick=()=>{token=el('code').value.trim();el('code').value='';load()};el('refresh').onclick=load;el('save').onclick=async()=>{if(!data)return;const controls=[...document.querySelectorAll('input,textarea,button,select')];const previous=controls.map(c=>c.disabled);controls.forEach(c=>c.disabled=true);try{data=await request('POST',data);dirty=false;render();el('error').textContent='';el('status').textContent='Saved · revision '+data.revision}catch(e){el('error').textContent=e.message}finally{controls.forEach((c,i)=>c.disabled=previous[i])}};window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&e.target.matches('input,textarea')){e.preventDefault();e.target.blur()}});
</script></html>)PORTAL";}
